update user_profiles set
  gender = case id
    when 'd0000000-0000-0000-0000-000000000003' then 'male'
    when 'd0000000-0000-0000-0000-000000000004' then 'female'
    when 'd0000000-0000-0000-0000-000000000005' then 'male'
    when 'd0000000-0000-0000-0000-000000000006' then 'female'
    when 'd0000000-0000-0000-0000-000000000007' then 'male'
    when 'd0000000-0000-0000-0000-000000000008' then 'female'
    when 'd0000000-0000-0000-0000-000000000010' then 'female'
    when 'd0000000-0000-0000-0000-000000000011' then 'male'
    when 'd0000000-0000-0000-0000-000000000012' then 'female'
    when 'd0000000-0000-0000-0000-000000000013' then 'male'
    else null end,
  dob = date '1994-01-01' + (extract(epoch from created_at)::int % 3000),
  created_by = case
    when id in ('d0000000-0000-0000-0000-000000000009',
                'd0000000-0000-0000-0000-000000000012')
    then 'd0000000-0000-0000-0000-000000000002'::uuid else null::uuid end
where id <> 'd0000000-0000-0000-0000-000000000001';

